$ErrorActionPreference='Stop'
$dir='D:\Projects\BuildingManagement-MVC\Resources'
function Load($n){$d=[xml](Get-Content (Join-Path $dir $n));return $d}
function Save($d,$n){$s=[System.Xml.XmlWriterSettings]::new();$s.Encoding=[System.Text.UTF8Encoding]::new($false);$s.Indent=$true;$w=[System.Xml.XmlWriter]::Create((Join-Path $dir $n),$s);try{$d.Save($w)}finally{$w.Dispose()}}
function Has($o,$k){return $null -ne $o.PSObject.Properties[$k]}
function Add($d,$k,$v){if($null -ne $d.SelectSingleNode("/root/data[@name='$k']")){return};$e=$d.CreateElement('data');$e.SetAttribute('name',$k);$a=$d.CreateAttribute('xml','space','http://www.w3.org/XML/1998/namespace');$a.Value='preserve';[void]$e.Attributes.Append($a);$n=$d.CreateElement('value');$n.InnerText=$v;[void]$e.AppendChild($n);[void]$d.DocumentElement.AppendChild($e)}
